(* [comment removed for export] *)
Lemma target_block_join : forall m A tbs jnk,
  rw_cells rsegs m A [C1 (b8 32)] -> rw_cells rsegs m (A + 1) [CB (length tbs) jnk] -> jnk = tbs ->
  rw_cells rsegs m A [CB (S (length tbs)) (b8 32 :: tbs)].
Proof.
  intros m A tbs jnk H1 H2 ->.
  assert (H1' : rw_cells rsegs m A [CB 1 [b8 32]]) by (eapply rw_cells_reshape; [exact H1 | cbn; split; reflexivity | reflexivity]).
  pose proof (rw_cells_CB_join rsegs _ _ _ _ _ _ H1' H2) as J. exact J.
Qed.

Section S2.
  Hypothesis S2V : string_to_verb_stmt.

(* [comment removed for export] *)
Definition req_seg2_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P verb MP TP ver lo At : Z) (mbs tbs : list byte) (h : hdrv) (m : mem) : machine_state -> Prop :=
  fun ms' =>
    (exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m2,
       verb <> 0
       /\ ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                F (ret_pc ra) fc None m2 (seg_rom rsegs)
       /\ munch [(lo, bv_unsigned sp); (At, At + (Z.of_nat (length tbs) + 1)); (P + O_PR_HDR, P + O_PR_HDR + 40)]%Z m m2
       /\ wmono rsegs m m2 /\ mem_inv rsegs m2 /\ stk rsegs m2 lo (bv_unsigned sp)
       /\ rw_cells rsegs m2 (P + O_PR_HDR) (HdrCells (mkHV 0 0 At (Z.of_nat (length tbs) + 1) ver verb))
       /\ rw_cells rsegs m2 At [CB (S (length tbs)) (b8 32 :: tbs)]
       /\ bytes_at rsegs m2 MP mbs /\ bytes_at rsegs m2 TP tbs)
    \/ (exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m2 j8,
       verb = 0
       /\ ms' = MS (mkR (wz RS_RET1) (Z_to_bv 64 (bv_unsigned sp + -128)) gp tp t0 t1 t2 (wz (P + 128)) (wz (Z.of_nat (length mbs)))
                     (wz (Z.of_nat (length mbs))) a1 a2 a3 a4 a5 a6 a7
                     (wz (Z.of_nat (length mbs))) (wz MP) (wz P) (wz 0) s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                F (wz ROPNEW) fc None m2 (seg_rom rsegs)
       /\ munch [(lo, bv_unsigned sp); (At, At + (Z.of_nat (length tbs) + 1)); (P + O_PR_HDR, P + O_PR_HDR + 40)]%Z m m2
       /\ wmono rsegs m m2 /\ mem_inv rsegs m2 /\ stk rsegs m2 lo (bv_unsigned sp + -128)
       /\ req_frames m2 sp ra s0 s1 s2 s3 s4 s5 j8 MP (Z.of_nat (length mbs)) (Z.of_nat (length mbs)) (P + 80) ver WK_RET_RS
       /\ rw_cells rsegs m2 (P + O_PR_HDR) (HdrCells (mkHV 0 0 At (Z.of_nat (length tbs) + 1) (hv_ver h) 0))
       /\ rw_cells rsegs m2 At [CB (S (length tbs)) (b8 32 :: tbs)]
       /\ bytes_at rsegs m2 MP mbs /\ bytes_at rsegs m2 TP tbs).

Definition req_seg2_stmt : Prop :=
  forall rax sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 (ra s0 s1 s2 s3 s4 s5 : word) s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P verb MP TP ver lo At : Z) (mbs tbs : list byte) (h : hdrv) (j8 junk : list byte),
  req_frames m sp ra s0 s1 s2 s3 s4 s5 j8 TP (Z.of_nat (length tbs)) (Z.of_nat (length mbs)) (P + 80) ver WK_RET_RT ->
  rw_cells rsegs m (P + O_PR_HDR) (HdrCells h) -> hdr_empty h ->
  rw_cells rsegs m At [CB (Z.to_nat (Z.of_nat (length tbs) + 1)) junk] -> rblock_range At (Z.of_nat (length tbs) + 1) ->
  bytes_at rsegs m MP mbs -> bytes_at rsegs m TP tbs ->
  (TP + Z.of_nat (length tbs) <= At \/ At + (Z.of_nat (length tbs) + 1) <= TP) ->
  (MP + Z.of_nat (length mbs) <= At \/ At + (Z.of_nat (length tbs) + 1) <= MP) ->
  (TP + Z.of_nat (length tbs) <= lo \/ bv_unsigned sp <= TP) -> (MP + Z.of_nat (length mbs) <= lo \/ bv_unsigned sp <= MP) ->
  stk rsegs m lo (bv_unsigned sp + -128) ->
  req_pure sp P MP TP lo mbs tbs -> 0 <= verb < 2^32 -> verb = verb_of (zbytes mbs) -> (ver = 10 \/ ver = 11) ->
  mem_inv rsegs m ->
  evt rsegs (req_seg2_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P verb MP TP ver lo At mbs tbs h m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -128)) gp tp t0 t1 t2 (wz (P + 144)) (wz (Z.of_nat (length tbs)))
              (wz At) a1 a2 a3 a4 a5 a6 a7
              (wz (Z.of_nat (length mbs))) (wz MP) (wz P) (wz verb) s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 RT_RET1) fc None m (seg_rom rsegs)).

