(* [comment removed for export] *)
Definition req_seg3_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P MP ver lo At Am : Z) (mbs tbs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m2,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m2 (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp); (Am, Am + Z.of_nat (length mbs)); (P + O_PR_HDR, P + O_PR_HDR + 40)]%Z m m2
    /\ wmono rsegs m m2 /\ mem_inv rsegs m2 /\ stk rsegs m2 lo (bv_unsigned sp)
    /\ rw_cells rsegs m2 (P + O_PR_HDR) (HdrCells (mkHV Am (Z.of_nat (length mbs)) At (Z.of_nat (length tbs) + 1) ver 0))
    /\ rw_cells rsegs m2 Am [CB (length mbs) mbs]
    /\ bytes_at rsegs m2 MP mbs.

